<?php require '../config/database.php';require '../config/auth.php';require_role('admin');if($_SERVER['REQUEST_METHOD']==='POST'){$q=$pdo->prepare('UPDATE queries SET reply=?,replied_at=NOW() WHERE id=?');$q->execute([trim($_POST['reply']),(int)$_POST['id']]);}$rows=$pdo->query('SELECT q.*,s.student_code FROM queries q JOIN students s ON s.id=q.student_id ORDER BY q.id DESC')->fetchAll();$page_title='Student Queries';require '../includes/header.php';?><h1>Student Queries</h1><div class="card"><table><tr><th>Student</th><th>Subject</th><th>Query</th><th>Reply</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['student_code']?></td><td><?=htmlspecialchars($r['subject'])?></td><td><?=htmlspecialchars($r['message'])?></td><td><form method="post"><input type="hidden" name="id" value="<?=$r['id']?>"><input name="reply" placeholder="Reply" value="<?=htmlspecialchars($r['reply']??'')?>"><button class="btn" style="margin-top:5px">Save Reply</button></form></td></tr><?php endforeach;?></table></div><?php require '../includes/footer.php';?>
